  ["data.otservbr.global.npc.amber.L427.529"] = "See you later, |PLAYERNAME|.",
  ["data.otservbr.global.npc.amber.L428.530"] = "Oh hello, nice to see you |PLAYERNAME|. Are you here to hear some stories of my {adventures} or do you need {help}?",
  ["data.otservbr.global.npc.anderson.L100.133"] = "Ahoi, young man |PLAYERNAME| and welcome to the Nordic Tibia Ferries. If you need a {passage}, let me know.",
  ["data.otservbr.global.npc.anderson.L101.134"] = "Good bye. You are welcome.",
  ["data.otservbr.global.npc.andrew.lyze.L101.514"] = "Hello, I am the warden of this {monument}. The {sarcophagus} in front of you was established to prevent people from going {down} there. But I doubt that this step is sufficient.",
  ["data.otservbr.global.npc.andrew.lyze.L103.515"] = "Well, let's see if your mission was successful. Just bring me all needed {materials}.",
  ["data.otservbr.global.npc.andrew.lyze.L105.516"] = "If you dug up all three crystals of sufficient quantity and obtained the poison gland, the charging of your compass can start! For the very first time it will be charged by the violet crystal. Ready to {unleash} the power of the crystals?",
  ["data.otservbr.global.npc.andrew.lyze.L107.517"] = "Greetings.",
  ["data.otservbr.global.npc.andrew.lyze.L263.518"] = "Well, bye then.",
