  ["data.otservbr.global.npc.angelina.L58.143"] = "The gods must be praised that I am finally saved. I do not have many worldly possessions, but please accept a small reward, do you?",
  ["data.otservbr.global.npc.angelina.L60.144"] = "Thanks for saving my life! Should I teleport you out of the Dark Cathedral?",
  ["data.otservbr.global.npc.angelina.L84.145"] = "May the gods bless you.",
  ["data.otservbr.global.npc.angelina.L85.146"] = "May the gods bless you.",
  ["data.otservbr.global.npc.angelo.L153.1447"] = "Well, bye then.",
  ["data.otservbr.global.npc.angelo.L58.1443"] = "The Druid of Crunor? He told you that a new cave appeared here? That's right. I'm the head of a {project} that tries to find out more about this new {area}.",
  ["data.otservbr.global.npc.angelo.L60.1444"] = "Just get out of my way! You killed this beautiful creature. I have nothing more to say. Damn druid of Crunor!",
