  ["data.otservbr.global.npc.the.orc.king.L61.114"] = "Harrrrk! You think you are strong now? You shall never escape my wrath! I am immortal!",
  ["data.otservbr.global.npc.the.queen.of.the.banshees.L215.943"] = "Be greeted, dear visitor. Come and {stay} ... a while.",
