  ["data.otservbr.global.npc.the.queen.of.the.banshees.L217.945"] = "Yes, flee from death. But know it shall be always one step behind you.",
  ["data.otservbr.global.npc.thorgrin.L67.258"] = "Welcome, |PLAYERNAME|! May earth protect you on the rocky grounds. If you need a {passage} back, I can help you.",
