  ["data.otservbr.global.npc.tom.L72.1437"] = "Hey there, |PLAYERNAME|. You look... exhausted. Did you run a lot? And more importantly, were you able to find some war wolf leather?",
  ["data.otservbr.global.npc.tom.L74.1438"] = "Hey there, |PLAYERNAME|. I'm Tom the tanner. If you have fresh {corpses}, leather, paws or other animal body parts, {trade} with me.",
