  ["data.otservbr.global.npc.zirella.L67.488"] = "Oh, heaven must have sent you! Could you please help me with a {quest}?",
  ["data.otservbr.global.npc.zirella.L70.489"] = "Welcome back, darling... so about that firewood, could you please {help} me?",
  ["data.otservbr.global.npc.zirella.L73.490"] = "Welcome back, darling... so about the {dead trees}, let me explain that a little more, {yes}?",
