  ["data.otservbr.global.npc.zirella.L79.492"] = "Welcome back, darling... so about the {pushing}, let me explain that a little more, {yes}?",
  ["data.otservbr.global.npc.zirella.L82.493"] = "Welcome back, darling... so about the {cart}, let me explain that a little more, {yes}?",
  ["data.otservbr.global.npc.zirella.L85.494"] = "Oh, sweetheart, is there a problem with the quest? Should I {explain} it again?",
  ["data.otservbr.global.npc.zirella.L88.495"] = "Right, thank you sweetheart! This will be enough to heat my oven. Oh, and you are probably waiting for your reward, {yes}?",
  ["data.otservbr.global.npc.zirella.L91.496"] = "Oh, welcome back, dear Isleth Eagonst! Are you here for a little chat? Just use the highlighted {keywords} again to choose a {topic}.",
  ["data.otservbr.global.npc.ziyad.L100.872"] = "Ah, the wind brings in another visitor. Welcome, dear guest. Are you looking for a {passage} with my carpet?",
  ["data.otservbr.global.npc.ziyad.L101.873"] = "Good bye. Recommend us if you were satisfied with our service.",
  ["data.otservbr.global.npc.ziyad.L102.874"] = "Good bye then.",
  ["data.otservbr.global.npc.zizzle.L114.1235"] = "Ah our human {alliez} have finally arrived! I've already feared zat ze emperor'z forzez had caught you. Your rezilienze and prowezz are imprezzive.",
  ["data.otservbr.global.npc.zlak.L103.716"] = "Juzt leave me alone.",
  ["data.otservbr.global.npc.znozel.L71.200"] = "Yes? What may I do for you, |PLAYERNAME|? Bank business, perhaps?",
  ["data.otservbr.global.npc.znozel.L72.201"] = "Have a nice day.",
  ["data.otservbr.global.npc.znozel.L73.202"] = "Have a nice day.",
  ["data.otservbr.global.npc.zoltan.L113.593"] = "Welcome |PLAYERNAME|, student of the arcane arts. I teach the fiercest {spells} available.",
  ["data.otservbr.global.npc.zoltan.L114.594"] = "Use your knowledge wisely, |PLAYERNAME|.",
  ["data.otservbr.global.npc.zora.L82.1328"] = "Oh, please come in, |PLAYERNAME|. What can I do for you? If you need adventure equipment, ask me for a {trade}.",
  ["data.otservbr.global.npc.zora.L83.1329"] = "Good bye, |PLAYERNAME|.",
  ["data.otservbr.global.npc.zora.L84.1330"] = "Good bye, |PLAYERNAME|.",
  ["data.otservbr.global.npc.zora.L85.1331"] = "Of course, just browse through my wares. {Footballs} have to be purchased separately.",
  ["data.otservbr.global.npc.ztiss.L98.98"] = "Be greeted my .. {guezt}.",
  ["data.otservbr.global.npc.zumtah.L141.1448"] = "Another visitor to this constricted, cosy, calm realm, perfect except for an {exit}. Muhaha.",
  ["data.otservbr.global.npc.zumtah.L142.1449"] = "Muhahaha.",
