  ["data.otservbr.global.scripts.quests.the.cursed.crystal.actions.MedusaOil.L50.1782"] = "You mixed the first ingredients to create a special ointment. But it isn't complete yet.",
  ["data.otservbr.global.scripts.quests.the.cursed.crystal.actions.MedusaOil.L55.1783"] = "You mixed the proper ingredients to create a special ointment. With this salve you may unpetrify a petrified object.",
  ["data.otservbr.global.scripts.quests.the.cursed.crystal.actions.MedusaOil.L65.1784"] = "Sorry, not possible.",
  ["data.otservbr.global.scripts.quests.the.cursed.crystal.actions.Misc.L105.1791"] = "You take some blood out of the hollow crystal. Hopefully it is actually a medusa's blood.",
  ["data.otservbr.global.scripts.quests.the.cursed.crystal.actions.Misc.L53.1785"] = "As you use the small bell, an unearthly sound rings out sweetly. At the same moment, the lake's waters begin to whirl.",
  ["data.otservbr.global.scripts.quests.the.cursed.crystal.actions.Misc.L63.1786"] = "A vortex already exists in this area.",
  ["data.otservbr.global.scripts.quests.the.cursed.crystal.actions.Misc.L82.1787"] = "You have found a sheet of paper.",
  ["data.otservbr.global.scripts.quests.the.cursed.crystal.actions.Misc.L90.1788"] = "The pile of bones is empty.",
  ["data.otservbr.global.scripts.quests.the.cursed.crystal.actions.Misc.L94.1789"] = "You have found a small crystal bell.",
  ["data.otservbr.global.scripts.quests.the.cursed.crystal.actions.Misc.L98.1790"] = "The pile of bones is empty.",
  ["data.otservbr.global.scripts.quests.the.cursed.crystal.actions.Ointment.L14.1777"] = "You unpetrify a banshee's scream near the evil crystal, your ears protected by wax. Thus the baleful artefact is destroyed.",
  ["data.otservbr.global.scripts.quests.the.cursed.crystal.movements.StepIn.CursedCrystal.L41.1778"] = "This small room could once have been a shrine of some kind. You discover an old inscription between two ornate stone walls.",
  ["data.otservbr.global.scripts.quests.the.cursed.crystal.movements.StepIn.CursedCrystal.L42.1779"] = "The text is partly crumbled: 'Take ... vial of emb... fl... and mix ... a medusa's bl.... Then .. the dust of ... crystal, so ... will get the Medusa's Ointm... powerful ... able to unpetrify ...",
  ["data.otservbr.global.scripts.quests.the.djinn.war.quest.action.water.fountain.L10.1917"] = "You have found a tear of daraman.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.acidFishingRod.L23.1839"] = "You dare not touch there remains. A word has been carved into these bones over and over: 'K'muuh'.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.bookOnTable.L14.1855"] = "This book tells you about a spell that draws its wielder towards the most energetic being next to him.",
