  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.key2.L14.2016"] = "Get out of my room!",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.key2.L9.2015"] = "An invisible hand pulls you inside.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.palanca.L6.2025"] = "<sizzle> <fizz>",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.pyramids1.L17.2013"] = "<sizzle> <fizz>",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.pyramids2.L18.2027"] = "<screeeech> <squeak> <squeaaaaal>",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.pyramids2.L21.2028"] = "Mission already completed here!",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.sacrifice.L7.2011"] = "The scroll burns to dust. The magic stutters. Omrabas' soul flees to his old hideaway.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.scroll.L6.2017"] = "Somebody left a card. It says: Looking for the scroll? Come find me. Take the stairs next to the students. Dorm.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.statue.L12.2018"] = "<BOOOOOOOONGGGGGG> A slow throbbing, like blood pulsing, runs through the floor.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.tears.L9.2021"] = "The dragon tears glow and disappear. The old powers are appeased.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.tincture.L9.2010"] = "You crash the vial and spill the blood tincture. This altar is anointed.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.movements.dormitory.teleport.L13.2007"] = "You should hurry, try not to dwell here any longer than a few minutes.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.movements.dormitory.teleport.L16.2008"] = "The teleport is accessible only once.",
